// Lip stages are a teaching animation. The TTS endpoint does not return phoneme timestamps.
const LIP_SHAPES={closed:[18,2],open:[25,17],narrow:[25,5],round:[12,13],mid:[22,10]};
const LIP_LABEL={closed:'唇を閉じる',open:'大きく開く',narrow:'横に狭く',round:'唇を丸める',mid:'口を開く'};
const LIP_MAP={
 '买':[['m','closed'],['a','open'],['i','narrow']], '卖':[['m','closed'],['a','open'],['i','narrow']],
 '水':[['sh','narrow'],['u','round'],['i','narrow']], '睡':[['sh','narrow'],['u','round'],['i','narrow']],
 '糖':[['t','closed'],['a','open'],['ng','mid']], '汤':[['t','closed'],['a','open'],['ng','mid']]
};
const PINYIN_HINT={'我':'wǒ','买':'mǎi','卖':'mài','一':'yí','个':'ge','你':'nǐ','好':'hǎo','吗':'ma','吃':'chī','饭':'fàn','了':'le','是':'shì','日':'Rì','本':'běn','人':'rén','中':'Zhōng','国':'guó','文':'wén','水':'shuǐ','睡':'shuì','糖':'táng','汤':'tāng','请':'qǐng','说':'shuō','不':'bù','谢':'xiè','去':'qù','哪':'nǎ','儿':'r','有':'yǒu','明':'míng','天':'tiān','想':'xiǎng','很':'hěn','可':'kě','以':'yǐ','这':'zhè','多':'duō','少':'shao','钱':'qián','现':'xiàn','在':'zài','知':'zhī','道':'dào','时':'shí','间':'jiān','要':'yào','上':'shàng','班':'bān'};
