const TTS_API='https://worker-xiaoshuang.wangjinyu00.workers.dev';
const STT_API=TTS_API+'/stt';
const ttsCache=new Map();
const ttsPending=new Map();
function fetchTTSBlobUrl(text){
  const key=String(text||'').trim();
  if(!key)return Promise.reject(new Error('empty'));
  if(ttsCache.has(key))return Promise.resolve(ttsCache.get(key));
  if(ttsPending.has(key))return ttsPending.get(key);
  const pending=(async()=>{
    const controller=new AbortController();
    const timer=setTimeout(()=>controller.abort(),12000);
    try{
      const r=await fetch(TTS_API,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:key}),signal:controller.signal});
      if(!r.ok){const detail=await r.text().catch(()=>'');throw new Error('TTS '+r.status+' '+detail.slice(0,120));}
      const blob=await r.blob();
      if(!blob.size)throw new Error('empty audio');
      const url=URL.createObjectURL(blob);
      ttsCache.set(key,url);
      return url;
    }finally{
      clearTimeout(timer);
      ttsPending.delete(key);
    }
  })();
  ttsPending.set(key,pending);
  return pending;
}
function prefetchTTS(text){
  const key=String(text||'').trim();
  if(!key||ttsCache.has(key)||ttsPending.has(key))return;
  fetchTTSBlobUrl(key).catch(()=>{});
}
