function chatToneTip(text){
 try{
  const tones=pinyinPro.pinyin(text,{pattern:'num',type:'array',nonZh:'removed'});
  if(tones.some(s=>/3$/.test(s)))return '声調メモ：三声があるよ。お手本の音の上下を聞いてみよう。';
  if(tones.some(s=>/4$/.test(s)))return '声調メモ：四声があるよ。音の下がり方を聞いてみよう。';
  if(tones.some(s=>/2$/.test(s)))return '声調メモ：二声があるよ。音の上がり方を聞いてみよう。';
 }catch(e){}
 return '声調メモ：ピンインを見ながら、お手本といっしょに言ってみよう。';
}

const IOS_AUDIO_PRIME='data:audio/wav;base64,';
function chatHearTap(event){
 const button=event?.currentTarget;
 if(!button)return false;
 event.preventDefault?.();
 event.stopPropagation?.();
 const now=Date.now();
 if(button._chatTapAt&&now-button._chatTapAt<350)return false;
 button._chatTapAt=now;
 const text=button.dataset.chatSpeak||'';
 const bubble=button.closest('.chat-bubble');
 const original=button.dataset.originalLabel||'🔊 この文のお手本を聞く';
 button.dataset.originalLabel=original;
 const url=button.dataset.audioUrl||ttsCache.get(text)||'';
 if(!url){
   chatNote('いま音声を準備中です。1秒ほど待って、もう一度押してね。');
   button.textContent='🔄 準備中…';
   if(!button._prefetching){
     button._prefetching=true;
     fetchTTSBlobUrl(text).then(u=>{
       button.dataset.audioUrl=u;
       if(button.isConnected){button.disabled=false;button.textContent=original;}
     }).catch(()=>{
       if(button.isConnected){button.disabled=false;button.textContent=original;}
     }).finally(()=>{button._prefetching=false;});
   }
   return false;
 }
 button.setAttribute('aria-busy','true');
 button.textContent='🔊 再生中…';
 Promise.resolve(playChatAudioFromUrl(text,url,bubble)).catch(()=>{
   chatNote('音声を再生できませんでした。もう一度🔊を押してね。');
 }).finally(()=>{
   if(button.isConnected){button.removeAttribute('aria-busy');button.textContent=original;}
 });
 return false;
}
function bindReliableTap(button,handler){
 button.type='button';
 button.style.touchAction='manipulation';
 button.style.webkitTapHighlightColor='transparent';
 button.onclick=event=>handler(event);
 button.ontouchend=event=>handler(event);
 button.onpointerup=event=>handler(event);
}
