function chatBubble(text,kind,options={}){
 const item=document.createElement('div');item.className='chat-bubble '+kind+(options.echo?' echo':'');
 if(options.echo){const label=document.createElement('span');label.className='chat-echo-label';label.textContent=options.lead?'🐼 小音が先に読む':'🐼 聞こえた言葉のお手本';item.appendChild(label)}
 item.appendChild(document.createTextNode(text));
 const py=chatPinyinFor(text);
 if(py){if(kind==='me'){const caption=document.createElement('span');caption.className='chat-pinyin-caption';caption.textContent='ピンイン・声調';item.appendChild(caption)}const row=document.createElement('div');row.className='chat-pinyin';row.lang='zh-Latn';row.setAttribute('aria-label',py);py.split(' ').forEach(syllable=>{const span=document.createElement('span');span.className='chat-pinyin-syllable';span.textContent=syllable;row.appendChild(span)});item.appendChild(row)}
 if(kind==='bot'&&options.gloss){const gloss=document.createElement('small');gloss.textContent=options.gloss;item.appendChild(gloss)}
 if(options.echo){const tip=document.createElement('small');tip.className='chat-practice-tip';tip.textContent=chatToneTip(text);item.appendChild(tip)}
 if(kind==='bot'){const hear=document.createElement('button');hear.type='button';hear.className='chat-hear-button';hear.textContent='🔄 お手本を準備中…';hear.dataset.chatSpeak=text;hear.dataset.originalLabel='🔊 この文のお手本を聞く';hear.setAttribute('aria-label',text+' のお手本を聞く');hear.disabled=true;bindReliableTap(hear,chatHearTap);item.appendChild(hear);fetchTTSBlobUrl(text).then(url=>{hear.dataset.audioUrl=url;if(hear.isConnected){hear.disabled=false;hear.textContent=hear.dataset.originalLabel;}}).catch(()=>{if(hear.isConnected){hear.disabled=false;hear.textContent=hear.dataset.originalLabel;}});}
 if(options.echo&&text.length<=60){const practice=document.createElement('button');practice.type='button';practice.className='chat-practice-button';practice.textContent='🎙 まねして言う';practice.addEventListener('click',()=>chatToggleRecording({practiceText:text,bubble:item,button:practice}));item.appendChild(practice);const result=document.createElement('span');result.className='chat-practice-result';result.setAttribute('role','status');result.hidden=true;item.appendChild(result)}
 const thread=getEl('chatThread');thread.appendChild(item);thread.scrollTop=thread.scrollHeight;
 return item;
}
function chatLead(text,options={}){
 if(chatBusy){chatNote('録音が終わってから選んでね。');return}
 chatAutoTurn=null;getEl('chatDraft').value='';chatUpdateDraftPinyin();getEl('chatComposeHint').textContent='';getEl('chatSend').textContent='🔊 小音に読んでもらう';
 chatArchiveCurrent();
 const bot=chatBubble(text,'bot',{echo:true,lead:true,gloss:CHAT_LEAD_GLOSS[text]||'小音の声を聞いて、声に出してみよう♪'});
 chatNote('小音のあとに続けて言ってみよう。何度でも大丈夫♪');
 if(!options.initial)void chatSpeak(text,{auto:true,bubble:bot});
}
function chatSend(options={}){
 const auto=options.auto===true;
 if(chatBusy&&!auto){chatNote('録音を停止してから送信してください。');return}
 const draft=getEl('chatDraft'),text=draft.value.trim();
 if(!text){chatNote('中国語を話すか、手書きで入力してください。');draft.focus();return}
 if(!/[\u3400-\u9fff]/u.test(text)){chatNote('中国語の漢字を含む文を入力してください。');return}
 if(!auto&&chatAutoTurn&&text===chatAutoTurn.text){chatAutoTurn=null;draft.value='';chatUpdateDraftPinyin();getEl('chatComposeHint').textContent='';getEl('chatSend').textContent='🔊 小音に読んでもらう';chatNote('この文字でいいね。お手本の🔊を押して聞いてみよう♪');return}
 const corrected=!auto&&!!chatAutoTurn;
 if(corrected){if(chatAudio)chatAudio.pause();hideMouthPop();chatAutoTurn.user.remove();chatAutoTurn.bot.remove();chatAutoTurn=null}
 chatArchiveCurrent();
 const user=chatBubble(text,'me'),bot=chatBubble(text,'bot',{echo:true,gloss:auto?'こう聞こえたよ。違っていたら文字を直してね。':'この一言を、小音といっしょに言ってみよう♪'});
 if(auto){chatAutoTurn={text,user,bot};chatUpdateDraftPinyin();getEl('chatSend').textContent='✏️ 文字を直してお手本更新';chatNote('聞こえた文を小音が読んでみるよ。違ったら文字を直してね。')}
 else{draft.value='';getEl('chatComposeHint').textContent='';chatUpdateDraftPinyin();getEl('chatSend').textContent='🔊 小音に読んでもらう';chatNote('お手本のあとに続けて言ってみよう♪')}
 void chatSpeak(text,{auto:true,bubble:bot});
}
async function chatSpeak(text,options={}){
 stopStandardAudio();
 const preparedAudio=options.preparedAudio||null;
 if(chatAudio&&chatAudio!==preparedAudio){try{chatAudio.pause()}catch(e){}chatAudio=null}
 if(preparedAudio)chatAudio=preparedAudio;
 activeChatBubble=options.bubble||null;activeChatPinyin=activeChatBubble?.querySelector('.chat-pinyin')||null;const playToken=mouthToken;
 chatNote('お手本の音声を準備しています…');
 try{
  const url=await fetchTTSBlobUrl(text);
  if(playToken!==mouthToken){if(preparedAudio){try{preparedAudio.pause()}catch(e){}}return;}
  let current;
  if(preparedAudio){
   current=preparedAudio;current.loop=false;current.volume=1;
   try{current.pause();current.src=url;current.currentTime=0;current.load()}catch(e){current.src=url}
   chatAudio=current;
  }else{chatAudio=new Audio(url);current=chatAudio;}
  current.addEventListener('playing',()=>startMouthPop(text,current,playToken),{once:true});
  current.addEventListener('ended',()=>{if(activeAudio===current)hideMouthPop()},{once:true});
  current.addEventListener('error',()=>{if(activeAudio===current)hideMouthPop()},{once:true});
  await current.play();if(playToken===mouthToken&&!current.paused)startMouthPop(text,current,playToken);
  chatNote('小音のあとに続けて、言ってみよう♪');
 }catch(e){if(preparedAudio){try{preparedAudio.pause()}catch(_){}}if(playToken!==mouthToken)return;hideMouthPop();chatNote('音声を再生できませんでした。もう一度🔊を押してね。')}
}
function chatRelease(){if(chatTimer){clearTimeout(chatTimer);chatTimer=null}if(chatStream){chatStream.getTracks().forEach(t=>t.stop());chatStream=null}}
function chatStop(){if(chatTimer){clearTimeout(chatTimer);chatTimer=null}if(chatRecorder&&chatRecorder.state==='recording'){chatRecorder.stop()}else chatRelease()}
function chatPracticeFeedback(target,data){
 if(!data.ok)return 'もう一度ゆっくり言ってみよう。お手本を聞き直しても大丈夫だよ♪';
 const heard=String(data.text||'').trim().replace(/[。！？?!，、\s]/g,'');const expected=target.trim().replace(/[。！？?!，、\s]/g,'');
 if(heard!==expected)return '「'+String(data.text||'').slice(0,60)+'」と聞こえたよ。文字が違っても大丈夫。お手本の一言を聞いて、もう一度試してみよう♪';
 if(data.assessmentAvailable&&Number.isFinite(Number(data.accuracyScore))&&Number.isFinite(Number(data.completenessScore))){
  if(Number(data.accuracyScore)>=78&&Number(data.completenessScore)>=75)return 'この一言、しっかり伝わったよ！いい感じ♪';
  return '言葉はちゃんと聞こえたよ！ピンインを見ながら、お手本の声調をまねしてみよう♪';
 }
 return 'この一言、ちゃんと聞こえたよ！お手本といっしょに、もう一度言ってみよう♪';
}
async function chatToggleRecording(options={}){
 if(chatRecorder&&chatRecorder.state==='recording'){chatStop();return}
 if(chatBusy)return;
 if(isRecording||starting||exampleRecording){chatNote('ほかの録音を止めてからお試しください。');return}
 if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){chatNote('このブラウザは録音に対応していません。中国語キーボードで入力できます。');return}
 const practice=options.practiceText&&options.bubble?.isConnected&&options.button?.isConnected?options:null;
 if(!practice){chatAutoTurn=null;getEl('chatSend').textContent='🔊 小音に読んでもらう';getEl('chatDraft').value='';chatUpdateDraftPinyin()}
 if(chatAudio){chatAudio.pause();chatAudio=null}hideMouthPop();
 chatBusy=true;const generation=++chatGeneration;chatNote('マイクを準備しています…');
 try{
  chatStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}});
  if(generation!==chatGeneration){chatRelease();return}
  const mime=['audio/mp4','audio/webm;codecs=opus','audio/webm'].find(m=>typeof MediaRecorder.isTypeSupported==='function'&&MediaRecorder.isTypeSupported(m));
  chatParts=[];chatRecorder=new MediaRecorder(chatStream,mime?{mimeType:mime}:undefined);
  chatRecorder.ondataavailable=e=>{if(e.data.size)chatParts.push(e.data)};
  chatRecorder.onerror=()=>{chatNote('録音できませんでした。もう一度試してね。');chatRelease();chatBusy=false;if(practice){practice.button.classList.remove('is-recording');practice.button.textContent='🎙 まねして言う'}};
  chatRecorder.onstop=async()=>{
   chatRelease();if(practice){practice.button.classList.remove('is-recording');practice.button.textContent='🎙 まねして言う'}else{getEl('chatMic').classList.remove('is-recording');getEl('chatMic').textContent='🎙 話す'}
   const blob=new Blob(chatParts,{type:chatRecorder.mimeType||mime||'audio/webm'});chatParts=[];
   if(!blob.size){chatBusy=false;chatNote('声が録れませんでした。もう一度お試しください。');return}
   chatNote(practice?'小音が発音を聞いてみるね…':'小音が聞いた言葉を見てみよう…');
   try{
    const wav=await recordedBlobToWav16kMono(blob);
    const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),18000);
    const endpoint=practice?STT_API+'?target='+encodeURIComponent(practice.practiceText):STT_API.replace(/\/stt$/,'/listen');
    let r;try{r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'audio/wav'},body:wav,signal:controller.signal})}finally{clearTimeout(timer)}
    if(!r.ok)throw Error('listen endpoint unavailable');
    const data=await r.json();if(generation!==chatGeneration)return;
    if(practice){const result=practice.bubble.querySelector('.chat-practice-result');if(result){const message=chatPracticeFeedback(practice.practiceText,data);const moods=[...document.querySelectorAll('.mood-strip img')];let moodIndex=1;if(!data.ok)moodIndex=3;else{const heard=String(data.text||'').trim().replace(/[。！？?!，、\s]/g,'');const expected=practice.practiceText.trim().replace(/[。！？?!，、\s]/g,'');if(heard!==expected)moodIndex=2;else if(data.assessmentAvailable&&Number(data.accuracyScore)>=78&&Number(data.completenessScore)>=75)moodIndex=0;}const moodSrc=moods[moodIndex]?.src||moods[0]?.src||'';result.innerHTML=(moodSrc?'<img class=\"chat-feedback-panda\" src=\"'+moodSrc+'\" alt=\"小音の表情\">':'<span class=\"chat-feedback-panda-fallback\">🐼</span>')+'<span class=\"chat-feedback-copy\">'+escapeHtml(message)+'</span>';result.hidden=false}chatNote('上手だよ。少しずつ声に出してみよう♪')}
    else if(data.ok&&data.text){getEl('chatDraft').value=String(data.text).slice(0,60);chatUpdateDraftPinyin();chatBusy=false;chatSend({auto:true})}
    else chatNote('ごめんね、もう一度聞かせてくれる？ 手書きでも大丈夫だよ。');
   }catch(e){if(generation===chatGeneration)chatNote(practice?'今は発音を確かめられなかったよ。お手本の🔊を聞いて、また試してね。':'音声認識を利用できません。手書きで入力しても大丈夫だよ。')}
   finally{chatBusy=false}
  };
  chatRecorder.start();if(practice){practice.button.textContent='■ 言い終わったらタップ';practice.button.classList.add('is-recording')}else{getEl('chatMic').textContent='■ 録音を止める';getEl('chatMic').classList.add('is-recording')}
  chatNote(practice?'お手本の一言を、ゆっくり言ってみよう♪（最大10秒）':'小音が聞いてるよ。短いひとことをどうぞ♪（最大10秒）');chatTimer=setTimeout(chatStop,10000);
 }catch(e){chatRelease();chatBusy=false;if(practice){practice.button.classList.remove('is-recording');practice.button.textContent='🎙 まねして言う'}chatNote('マイクを利用できません。HTTPSで開いて権限を確認するか、手書きで入力してください。')}
}
